async function c(t){if(!/^image\/(jpeg|png|webp|heic|heif)$/i.test(t.type))return t;try{const a=await createImageBitmap(t,{imageOrientation:"from-image"}),i=Math.min(1,2e3/Math.max(a.width,a.height));if(i===1&&t.size<=409600)return a.close(),t;const e=document.createElement("canvas");e.width=Math.round(a.width*i),e.height=Math.round(a.height*i);const n=e.getContext("2d");if(!n)return t;n.fillStyle="#fff",n.fillRect(0,0,e.width,e.height),n.drawImage(a,0,0,e.width,e.height),a.close();const o=await new Promise(r=>e.toBlob(r,"image/jpeg",.85));return o&&o.size<t.size?o:t}catch{return t}}export{c as r};
